import React from 'react';
import { Card, Tr, Tr4, S, SectionTitle } from './summaryComponents';

const n = (v: any) => { const num = parseFloat(v); return isNaN(num) ? 0 : num; };
const fmt = (v: number) => v.toFixed(2).replace(/\.00$/, '');
const fm = (v: number) => v.toLocaleString('en-US', { maximumFractionDigits: 0 });

export const SummaryTables1 = ({ data, o, setO, cur, cv, floors, settings, update, allOpen, toggleAll, onUpdateFloors }: any) => {
  const { buildingArea, prelim, struct, finishes, prices } = data;

    const footingConcrete = n(struct.footingConcrete);
      const neckConcrete = n(struct.neckConcrete);
        const columnConcrete = n(struct.columnConcrete) * floors;
          const middConcrete = n(struct.middConcrete);
            const slabConcrete = n(struct.slabConcrete) * floors;
              const totalConcrete = footingConcrete + neckConcrete + columnConcrete + middConcrete + slabConcrete;

                const footingSteel = n(struct.footingSteel);
                  const neckSteel = n(struct.neckSteel);
                    const columnSteel = n(struct.columnSteel) * floors;
                      const middSteel = n(struct.middSteel);
                        const slabSteel = n(struct.slabSteel) * floors;
                          const totalSteel = footingSteel + neckSteel + columnSteel + middSteel + slabSteel;

                            const excavation = Math.ceil(n(prelim?.excavationVolume) || 0);
                              const backfill = Math.ceil(n(prelim?.backfillVolume) || 0);
                                const stoneArea = Math.ceil(n(prelim?.plinthArea) || 0);

                                  const steelPrice = n(prices.steelUnified || '0');
                                    const concPrice = n(prices.concrete?.[1]?.price || prices.concrete?.[0]?.price || '0');
                                      const blockPrice = n(prices.finishesMaterials?.[0]?.price || '0');

                                        const excPrice = n(prices.preliminary?.[0]?.price || '0');
                                          const backPrice = n(prices.preliminary?.[1]?.price || '0');
                                            const stonePrice = n(prices.preliminary?.[2]?.price || '0');
                                              const excCost = excavation * excPrice;
                                                const backCost = backfill * backPrice;
                                                  const stoneCost = stoneArea * stonePrice;
                                                    const prelimCost = excCost + backCost + stoneCost;

                                                      const totalConcreteCost = totalConcrete * concPrice;
                                                        const totalSteelCost = totalSteel * steelPrice;

                                                          const totalBlocks = Math.ceil(buildingArea * 5 * floors);
                                                            const totalBlocksCost = totalBlocks * blockPrice;

                                                              const materialsTotal = totalConcreteCost + totalSteelCost + totalBlocksCost + prelimCost;

                                                                const laborPrice = n(prices.labor?.[0]?.price || '0');
                                                                  // ✅ تصحيح السقف: مساحة المسقط × 0.3 × عدد الأدوار
                                                                    const slabConcreteForLabor = buildingArea * 0.3 * floors;
                                                                      const laborTotal =
                                                                          footingConcrete * laborPrice +
                                                                              neckConcrete * laborPrice +
                                                                                  columnConcrete * laborPrice +
                                                                                      middConcrete * laborPrice +
                                                                                          slabConcreteForLabor * laborPrice;

                                                                                            let extrasCost = 0;
                                                                                              (prices.other || []).forEach((e: any) => {
                                                                                                  extrasCost += e.costType === 'fixed' ? n(e.price) : (totalSteelCost + totalConcreteCost) * n(e.price) / 100;
                                                                                                    });

                                                                                                      return (
                                                                                                          <>
                                                                                                                {/* إعدادات العملة */}
                                                                                                                      <div style={S.card}>
                                                                                                                              <div style={S.body}>
                                                                                                                                        <div style={{ display: 'flex', gap: '8px', alignItems: 'flex-end' }}>
                                                                                                                                                    <div style={{ flex: 1 }}>
                                                                                                                                                                  <label style={{ fontSize: '0.6rem', color: '#003366', display: 'block', marginBottom: '2px', fontWeight: 700 }}>العملة</label>
                                                                                                                                                                                <select value={settings.currency} onChange={e => update('currency', e.target.value)} style={{ width: '100%', border: '1px solid #ccc', borderRadius: '8px', padding: '6px 12px', fontSize: '0.85rem', fontFamily: 'Cairo, sans-serif', fontWeight: 700, background: 'white' }}>
                                                                                                                                                                                                <option value="YER">ريال يمني</option>
                                                                                                                                                                                                                <option value="SAR">ريال سعودي</option>
                                                                                                                                                                                                                                <option value="USD">دولار</option>
                                                                                                                                                                                                                                              </select>
                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                      {settings.currency !== 'YER' && (
                                                                                                                                                                                                                                                                                    <div style={{ flex: 1 }}>
                                                                                                                                                                                                                                                                                                    <label style={{ fontSize: '0.6rem', color: '#003366', display: 'block', marginBottom: '2px', fontWeight: 700 }}>سعر الصرف</label>
                                                                                                                                                                                                                                                                                                                    <input type="text" inputMode="decimal" defaultValue={settings.rate} onBlur={e => update('rate', e.target.value)} onFocus={e => e.target.select()} placeholder="1" style={{ width: '100%', border: '1px solid #ccc', borderRadius: '8px', padding: '6px 8px', fontSize: '0.85rem', textAlign: 'center', fontFamily: 'Cairo, sans-serif', fontWeight: 700, background: 'white' }} />
                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                            {/* بيانات المشروع */}
                                                                                                                                                                                                                                                                                                                                                                                  <div style={S.card}>
                                                                                                                                                                                                                                                                                                                                                                                          <div style={S.body}>
                                                                                                                                                                                                                                                                                                                                                                                                    <SectionTitle>بيانات المشروع</SectionTitle>
                                                                                                                                                                                                                                                                                                                                                                                                              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                        <label style={{ fontSize: '0.6rem', color: '#003366', display: 'block', marginBottom: '2px', fontWeight: 700 }}>اسم المشروع</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input type="text" defaultValue={localStorage.getItem('project_name') || ''} onBlur={e => localStorage.setItem('project_name', e.target.value)} style={{ width: '100%', border: '1px solid #ccc', borderRadius: '8px', padding: '6px 8px', fontSize: '0.85rem', textAlign: 'right', fontFamily: 'Cairo, sans-serif', fontWeight: 700, background: 'white' }} placeholder="اسم المشروع" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <label style={{ fontSize: '0.6rem', color: '#003366', display: 'block', marginBottom: '2px', fontWeight: 700 }}>المالك</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input type="text" defaultValue={localStorage.getItem('project_owner') || ''} onBlur={e => localStorage.setItem('project_owner', e.target.value)} style={{ width: '100%', border: '1px solid #ccc', borderRadius: '8px', padding: '6px 8px', fontSize: '0.85rem', textAlign: 'right', fontFamily: 'Cairo, sans-serif', fontWeight: 700, background: 'white' }} placeholder="اسم المالك" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label style={{ fontSize: '0.6rem', color: '#003366', display: 'block', marginBottom: '2px', fontWeight: 700 }}>المهندس</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <input type="text" defaultValue={localStorage.getItem('project_engineer') || ''} onBlur={e => localStorage.setItem('project_engineer', e.target.value)} style={{ width: '100%', border: '1px solid #ccc', borderRadius: '8px', padding: '6px 8px', fontSize: '0.85rem', textAlign: 'right', fontFamily: 'Cairo, sans-serif', fontWeight: 700, background: 'white' }} placeholder="اسم المهندس" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label style={{ fontSize: '0.6rem', color: '#003366', display: 'block', marginBottom: '2px', fontWeight: 700 }}>مساحة المشروع</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input type="text" readOnly value={`${fmt(buildingArea)} م²`} style={{ width: '100%', border: '1px solid #ccc', borderRadius: '8px', padding: '6px 8px', fontSize: '0.85rem', textAlign: 'center', fontFamily: 'Cairo, sans-serif', fontWeight: 700, background: '#f8fafc' }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* زر فتح/طي + عدد الأدوار + زر تحديث البيانات */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button onClick={toggleAll} style={{ padding: '8px', border: '1px solid #00509e', borderRadius: '8px', background: '#f0f5ff', color: '#00509e', fontWeight: 700, fontSize: '0.8rem', cursor: 'pointer', fontFamily: 'Cairo, sans-serif' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {allOpen ? 'طي جميع الجداول' : 'فتح جميع الجداول'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <label style={{ fontSize: '0.8rem', fontWeight: 700, color: '#003366' }}>عدد الأدوار:</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <input type="text" inputMode="decimal" defaultValue={settings.floors} onBlur={e => update('floors', e.target.value)} onFocus={e => e.target.select()} style={{ width: '50px', border: '1px solid #ccc', borderRadius: '8px', padding: '6px 8px', fontSize: '0.85rem', textAlign: 'center', fontFamily: 'Cairo, sans-serif', fontWeight: 700, background: 'white' }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button onClick={onUpdateFloors} style={{ padding: '8px', border: 'none', borderRadius: '8px', background: '#00509e', color: 'white', fontWeight: 700, fontSize: '0.8rem', cursor: 'pointer', fontFamily: 'Cairo, sans-serif' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              تحديث البيانات
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* كميات وتكلفة الأعمال التمهيدية */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Card title={`كميات وتكلفة الأعمال التمهيدية (${cur})`} open={o.prel} setOpen={() => setO((p: any) => ({ ...p, prel: !p.prel }))}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.7rem' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <thead><tr><th style={S.th}>البند</th><th style={S.th}>الكمية</th><th style={S.th}>السعر</th><th style={S.th}>الإجمالي</th></tr></thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Tr4 label="الحفر" qty={`${fmt(excavation)} م³`} price={fm(cv(excPrice))} total={fm(cv(excCost))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Tr4 label="الدفان" qty={`${fmt(backfill)} م³`} price={fm(cv(backPrice))} total={fm(cv(backCost))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Tr4 label="الكرسي الحجري" qty={`${fmt(stoneArea)} م²`} price={fm(cv(stonePrice))} total={fm(cv(stoneCost))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Tr4 label="إجمالي الأعمال التمهيدية" qty="" price="" total={`${fm(cv(prelimCost))} ${cur}`} totalRow />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </Card>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* كميات الخرسانة */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Card title="كميات الخرسانة" open={o.conc} setOpen={() => setO((p: any) => ({ ...p, conc: !p.conc }))}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.7rem' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <thead><tr><th style={S.th}>البند</th><th style={S.th}>الكمية (م³)</th></tr></thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Tr label="القواعد" value={fmt(footingConcrete)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Tr label="الرقاب" value={fmt(neckConcrete)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Tr label={`الأعمدة (${floors} دور)`} value={fmt(columnConcrete)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Tr label="الميدات" value={fmt(middConcrete)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Tr label={`السقف (${floors} دور)`} value={fmt(slabConcrete)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Tr label="الإجمالي" value={`${fmt(totalConcrete)} م³`} total />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Card>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {/* كميات الحديد */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Card title="كميات الحديد" open={o.steel} setOpen={() => setO((p: any) => ({ ...p, steel: !p.steel }))}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.7rem' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <thead><tr><th style={S.th}>البند</th><th style={S.th}>الكمية (طن)</th></tr></thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Tr label="القواعد" value={fmt(footingSteel)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Tr label="الرقاب" value={fmt(neckSteel)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Tr label={`الأعمدة (${floors} دور)`} value={fmt(columnSteel)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Tr label="الميدات" value={fmt(middSteel)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Tr label={`السقف (${floors} دور)`} value={fmt(slabSteel)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Tr label="الإجمالي" value={`${fmt(totalSteel)} طن`} total />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </Card>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* تكلفة المواد */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Card title={`تكلفة المواد (${cur})`} open={o.mat} setOpen={() => setO((p: any) => ({ ...p, mat: !p.mat }))}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.7rem' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <thead><tr><th style={S.th}>المادة</th><th style={S.th}>الكمية</th><th style={S.th}>سعر الوحدة</th><th style={S.th}>الإجمالي</th></tr></thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Tr4 label="الخرسانة" qty={`${fmt(totalConcrete)} م³`} price={fm(cv(concPrice))} total={fm(cv(totalConcreteCost))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Tr4 label="الحديد" qty={`${fmt(totalSteel)} طن`} price={fm(cv(steelPrice))} total={fm(cv(totalSteelCost))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Tr4 label={`البلوك الهوردي (${floors} دور)`} qty={`${fmt(totalBlocks)} بلوكة`} price={fm(cv(blockPrice))} total={fm(cv(totalBlocksCost))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Tr4 label="إجمالي المواد" qty="" price="" total={`${fm(cv(materialsTotal))} ${cur}`} totalRow />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </Card>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* أجور المقاول */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Card title={`أجور المقاول (${cur})`} open={o.labor} setOpen={() => setO((p: any) => ({ ...p, labor: !p.labor }))}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.7rem' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <thead><tr><th style={S.th}>البند</th><th style={S.th}>الكمية</th><th style={S.th}>الأجرة</th><th style={S.th}>الإجمالي</th></tr></thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Tr4 label="الأساسات" qty={`${fmt(footingConcrete)} م³`} price={fm(cv(laborPrice))} total={fm(cv(footingConcrete * laborPrice))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Tr4 label="الرقاب" qty={`${fmt(neckConcrete)} م³`} price={fm(cv(laborPrice))} total={fm(cv(neckConcrete * laborPrice))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Tr4 label={`الأعمدة (${floors} دور)`} qty={`${fmt(columnConcrete)} م³`} price={fm(cv(laborPrice))} total={fm(cv(columnConcrete * laborPrice))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Tr4 label="الميدات" qty={`${fmt(middConcrete)} م³`} price={fm(cv(laborPrice))} total={fm(cv(middConcrete * laborPrice))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Tr4 label={`السقف (${floors} دور)`} qty={`${fmt(slabConcreteForLabor)} م³`} price={fm(cv(laborPrice))} total={fm(cv(slabConcreteForLabor * laborPrice))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Tr4 label="إجمالي أجور المقاول" qty="" price="" total={`${fm(cv(laborTotal))} ${cur}`} totalRow />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Card>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {/* مصاريف إضافية */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {prices.other?.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Card title={`مصاريف إضافية (${cur})`} open={o.extra} setOpen={() => setO((p: any) => ({ ...p, extra: !p.extra }))}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.7rem' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <thead><tr><th style={S.th}>البند</th><th style={S.th}>القيمة</th></tr></thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {prices.other.map((e: any, i: number) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const val = e.costType === 'fixed' ? n(e.price) : (totalSteelCost + totalConcreteCost) * n(e.price) / 100;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return <Tr key={i} label={e.name} value={`${fm(cv(val))} ${cur}`} />;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Tr label="إجمالي المصاريف" value={`${fm(cv(extrasCost))} ${cur}`} total />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };